      if (candidateFinish > (predecessorPath.length === 0 ? -1 : earliest[predecessorPath.at(-1)!].finish) ||
          (candidateFinish === (predecessorPath.length === 0 ? -1 : earliest[predecessorPath.at(-1)!].finish) &&
           paths.get(dependency)!.join("\u0000") < predecessorPath.join("\u0000"))) {
        predecessorPath = paths.get(dependency)!;
      }
    }
    const finish = start + task.duration;
    earliest[id] = { start, finish };
    const path = [...predecessorPath, id];
    paths.set(id, path);
    while (layers.length <= layer) layers.push([]);
    layers[layer].push(id);
    if (finish > totalDuration || (finish === totalDuration && path.join("\u0000") < criticalPath.join("\u0000"))) {
      totalDuration = finish;
      criticalPath = path;
    }
  }
  for (const layer of layers) layer.sort();
  return { order, layers, earliest, totalDuration, criticalPath };
}

async function main(): Promise<void> {
  const args = Bun.argv.slice(2);
  if (args.length !== 2 || args[0] !== "plan" || args[1].startsWith("-")) {
    fail("Usage: bun run src/cli.ts plan INPUT.json");
  }
  let text: string;
  try {
    text = await Bun.file(args[1]).text();
  } catch {
    fail(`Cannot read input file '${args[1]}'.`);
  }
  let input: unknown;
  try {
    input = JSON.parse(text);
  } catch {
    fail("Invalid JSON input.");
  }
  console.log(JSON.stringify(plan(input)));
}

if (import.meta.main) {
  main().catch((error: unknown) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}
# Dependency Planner

Dependency-free TypeScript CLI for Bun that validates a task graph and produces a deterministic execution plan.

```sh
bun run src/cli.ts plan INPUT.json
```

The input must be JSON with a `tasks` array. Each task has a unique non-empty string `id`, a finite non-negative numeric `duration`, and optional `dependsOn` string ids.

```json
{"tasks":[{"id":"lint","duration":1},{"id":"build","duration":3,"dependsOn":["lint"]}]}
```

The command writes exactly one JSON object to stdout on success: topological `order`, concurrent `layers`, unlimited-parallelism `earliest` times, `totalDuration`, and a deterministic `criticalPath`. Invalid input or cycles write an explanation to stderr and exit non-zero.

